<template><div class="app-container"><el-card><template #header>{{props.title}}</template><el-button type="primary" @click="load">刷新</el-button><el-table v-loading="loading" :data="rows" border><el-table-column v-for="c in props.columns" :key="c.prop" :prop="c.prop" :label="c.label"><template #default="s">{{display(s.row[c.prop])}}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column></el-table><Pagination v-show="total>0" v-model:page="page.current" v-model:limit="page.size" :total="total" @pagination="load"/></el-card></div></template>
<script setup>import{pageConfigs,toCrudProps}from'@/views/pageConfig';import{useCrudPage}from'@/views/useCrudPage';import{pageApi}from'./api';const props={...toCrudProps(pageConfigs.social,pageApi,{fetch:'socialDetails',remove:'deleteSocialDetails'}),title:'第三方登录配置'};const{loading,rows,total,page,display,load,remove}=useCrudPage(props)</script>
